"""Read-only review of submission wording and embedded PDF metadata."""
from pathlib import Path
import json
import re
import zipfile
import zlib

root = Path(__file__).resolve().parents[2]
archive = root / 'outputs/submission/DocuCheck_AI_Week2_FINAL_v3.zip'
patterns = {
    'ai_tool_names': r'(?i)chatgpt|openai|codex|claude|copilot|gemini|AI.generated|generated by AI',
    'workflow_or_review_language': r'(?i)assistant|prompt|workspace|người dùng|biên tập|human|user|agent|\.venv|C:[/\\]|pending.confirmation|adjudication',
}
matches = []
pdf_metadata = []
with zipfile.ZipFile(archive) as z:
    for name in z.namelist():
        data = z.read(name)
        if name.endswith(('.json', '.md', '.txt', '.csv')):
            for i, line in enumerate(data.decode('utf-8-sig').splitlines(), 1):
                for category, pattern in patterns.items():
                    if re.search(pattern, line):
                        matches.append({'file': name, 'line': i, 'category': category, 'text': line})
        elif name.endswith('.pdf'):
            chunks = [data]
            for m in re.finditer(rb'stream\r?\n(.*?)\r?\nendstream', data, re.S):
                try:
                    chunks.append(zlib.decompress(m.group(1)))
                except zlib.error:
                    pass
            for chunk in chunks:
                for m in re.finditer(rb'/(?:Creator|Producer|Author|Title)\s*(?:\((?:\\.|[^)])*\)|<[0-9a-fA-F]+>)', chunk):
                    pdf_metadata.append({'file': name, 'entry': m.group().decode('latin1')})
                for label in ('ChatGPT', 'OpenAI', 'Codex', 'Claude', 'Copilot', 'Gemini'):
                    if any(token in chunk.lower() for token in (label.lower().encode(), label.lower().encode('utf-16-be'))):
                        matches.append({'file': name, 'category': 'pdf_tool_name_bytes', 'text': label})

report_text = (root / 'reports/submission_week2/qa/extracted.txt').read_text(encoding='utf-8')
report_hits = {category: re.findall(pattern, report_text) for category, pattern in patterns.items()}
result = {'archive': str(archive.relative_to(root)), 'matches': matches, 'pdf_metadata': pdf_metadata,
          'report_text_matches': report_hits, 'changes_to_submission': False}
out = root / 'reports/submission_week2/evidence/submission_language_audit.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding='utf-8')
print(json.dumps(result, ensure_ascii=False, indent=2))
